//! Support for decrypting and decoding save files.

use anyhow::Result;
use chrono::{Datelike, NaiveDate, NaiveDateTime, Timelike};
use serde::{Deserialize, Serialize};
use serde_big_array::BigArray;
use shin_primitives::bit_utils::{BitBuffer, BitReadError, bit_read, bit_write};

use crate::{crc32, format::save::index_set::IndexSet};

pub mod index_set;
mod obfuscation;

const GAME_KEY: u32 = SaveData::obfuscation_key_from_seed("うみねこのなく頃に咲");

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SaveData {
    pub save_menu_position: u8,
    pub play_seconds: u32,
    pub persist_data: PersistData,
    pub save_vectors: SaveVectors,
    pub settings: Settings,
    pub auto_save_slot: Option<GameData>,
    #[serde(with = "BigArray")]
    pub manual_save_slots: [Option<GameData>; 100],
}

impl SaveData {
    pub const fn obfuscation_key_from_seed(seed: &str) -> u32 {
        crc32::crc32(seed.as_bytes(), 0)
    }

    /// Same as [SaveData::deobfuscate_with_key], but with fixed game key.
    pub fn deobfuscate(obfuscated_data: &[u8]) -> Result<Vec<u8>> {
        Self::deobfuscate_with_key(obfuscated_data, GAME_KEY)
    }

    /// Decrypts the game data, returning the raw decrypted bytes.
    /// Can fail if the CRC check fails.
    pub fn deobfuscate_with_key(obfuscated_data: &[u8], key: u32) -> Result<Vec<u8>> {
        obfuscation::decode(obfuscated_data, key)
    }

    /// Same as [SaveData::obfuscate_with_key], but with fixed game key.
    pub fn obfuscate(data: &[u8]) -> Vec<u8> {
        Self::obfuscate_with_key(data, GAME_KEY)
    }

    /// Encrypts the game data, returning the raw encrypted bytes.
    pub fn obfuscate_with_key(data: &[u8], key: u32) -> Vec<u8> {
        obfuscation::encode(data, key)
    }

    /// Same as [SaveData::decode_with_key], but with fixed game key.
    pub fn decode(obfuscated_data: &[u8]) -> Result<Self> {
        Self::decode_with_key(obfuscated_data, GAME_KEY)
    }

    /// Decrypts & decodes the game data, returning the parsed data.
    /// Can fail if the CRC check fails or the decoding fails.
    pub fn decode_with_key(obfuscated_data: &[u8], key: u32) -> Result<Self> {
        let deobfuscated_data = Self::deobfuscate_with_key(obfuscated_data, key)?;
        Self::decode_raw(deobfuscated_data)
    }

    pub fn decode_raw(deobfuscated_data: Vec<u8>) -> Result<Self> {
        let mut reader = BitBuffer::with_data(deobfuscated_data, 0);
        Ok(Self::read(&mut reader)?)
    }

    pub fn encode(&self) -> Vec<u8> {
        self.encode_with_key(GAME_KEY)
    }

    pub fn encode_with_key(&self, key: u32) -> Vec<u8> {
        let deobfuscated_data = self.encode_raw();
        let obfuscated_data = Self::obfuscate_with_key(&deobfuscated_data, key);

        obfuscated_data
    }

    pub fn encode_raw(&self) -> Vec<u8> {
        let mut writer = BitBuffer::empty();
        self.write(&mut writer);
        let (deobfuscated_data, _) = writer.into_data();
        deobfuscated_data
    }

    fn read(reader: &mut BitBuffer) -> Result<Self, BitReadError> {
        let some_ctr: u32 = reader.read_int(8)?;
        if some_ctr == 0 {
            todo!("Construct default Savedata")
        }
        if some_ctr > 1 {
            panic!("Invalid Savedata: some_ctr > 1")
        }

        let save_menu_position = reader.read_int(7)?;
        let play_seconds = reader.read_int(32)?;
        reader.align();

        let persist_data = PersistData::read(reader)?;
        let save_vectors = SaveVectors::read(reader)?;
        let settings = Settings::read(reader)?;
        let auto_save_slot = bit_read::read_opt(reader, GameData::read)?;
        let manual_save_slots =
            bit_read::read_array(reader, |r| bit_read::read_opt(r, GameData::read))?;

        Ok(Self {
            save_menu_position,
            play_seconds,
            persist_data,
            save_vectors,
            settings,
            auto_save_slot,
            manual_save_slots,
        })
    }

    fn write(&self, writer: &mut BitBuffer) {
        let &Self {
            save_menu_position,
            play_seconds,
            ref persist_data,
            ref save_vectors,
            ref settings,
            ref auto_save_slot,
            ref manual_save_slots,
        } = self;

        writer.write_int(8, 1); // some_ctr

        writer.write_int(7, save_menu_position);
        writer.write_int(32, play_seconds);
        writer.align();

        PersistData::write(persist_data, writer);
        SaveVectors::write(save_vectors, writer);
        Settings::write(settings, writer);
        bit_write::write_opt(auto_save_slot, writer, GameData::write);
        bit_write::write_array(manual_save_slots, writer, |d, w| {
            bit_write::write_opt(d, w, GameData::write)
        });
    }
}

/// Stores the persistent variables used by the VM.
/// They are independent of the save slots, used for stuff like global progression.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct PersistData(pub Vec<i16>);

impl PersistData {
    const ALLOC_AHEAD: usize = 0x40;

    pub fn new() -> Self {
        Self(Vec::new())
    }

    pub fn get(&self, index: usize) -> i32 {
        if index >= self.0.len() {
            0
        } else {
            self.0[index] as i32
        }
    }

    pub fn set(&mut self, index: usize, value: i32) {
        if self.0.len() <= index {
            // allocate more space, round up to 64
            let new_len = index.next_multiple_of(Self::ALLOC_AHEAD);
            self.0.resize(new_len, 0);
        }
        self.0[index] = value.try_into().expect("value too large");
    }

    fn read(reader: &mut BitBuffer) -> bit_read::Result<Self> {
        let data = bit_read::read_vec(reader, bit_read::read_u16, bit_read::read_i16)?;

        assert_eq!(data.len() % Self::ALLOC_AHEAD, 0);

        Ok(Self(data))
    }

    fn write(&self, writer: &mut BitBuffer) {
        let data = &self.0;

        assert_eq!(data.len() % Self::ALLOC_AHEAD, 0);

        bit_write::write_vec(data, writer, bit_write::write_u16, bit_write::write_i16);
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SaveVectors {
    /// This stores a mask of all seen messages to not skip unseen messages (if the setting is enabled)
    pub seen_messages: IndexSet,
    /// This stores a mask of all seen choice variants to change how they are displayed
    pub select_seen_choices: IndexSet,
    /// This stores the last variant chosen. Not sure if the game uses this information
    pub select_last_choices: Vec<u8>,
    /// This stores indices of unlocked CGs
    pub unlocked_cgs: IndexSet,
    /// This stores indices of unlocked BGMs
    pub unlocked_bgms: IndexSet,
    /// This stores indices of unlocked movies
    pub unlocked_movies: IndexSet,
}

impl SaveVectors {
    fn read(reader: &mut BitBuffer) -> bit_read::Result<Self> {
        reader.align();

        let seen_messages = IndexSet::read(reader)?;
        let select_seen_choices = IndexSet::read(reader)?;
        let select_last_choices =
            bit_read::read_vec(reader, bit_read::read_u16, |r| r.read_int(4))?;
        let unlocked_cgs = IndexSet::read(reader)?;
        let unlocked_bgms = IndexSet::read(reader)?;
        let unlocked_movies = IndexSet::read(reader)?;

        Ok(Self {
            seen_messages,
            select_seen_choices,
            select_last_choices,
            unlocked_cgs,
            unlocked_bgms,
            unlocked_movies,
        })
    }

    fn write(&self, writer: &mut BitBuffer) {
        let Self {
            seen_messages,
            select_seen_choices,
            select_last_choices,
            unlocked_cgs,
            unlocked_bgms,
            unlocked_movies,
        } = self;

        writer.align();
        IndexSet::write(seen_messages, writer);
        IndexSet::write(select_seen_choices, writer);
        bit_write::write_vec(
            select_last_choices,
            writer,
            bit_write::write_u16,
            |&i, w| w.write_int(4, i),
        );
        IndexSet::write(unlocked_cgs, writer);
        IndexSet::write(unlocked_bgms, writer);
        IndexSet::write(unlocked_movies, writer);
    }
}

/// Stores game settings
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Settings {
    // it appears that some settings do not have an in-game toggle
    pub v0_bgmvol: u8,
    pub v1_sfxvol: u8,
    pub v2_voicevol: u8,
    pub v3_sysvol: u8,
    pub v4_voicefocus: bool,
    pub v5_voicepanapot: bool,
    pub v6: bool,
    pub v7: u8,
    pub v8: u8,
    pub v9_msgspeed: u8,
    pub v10_skipspeed: u8,
    pub v11_disallowskipunread: bool,
    pub v12: bool,
    pub v13_msgwinalpha: u8,
    pub v14_showroutenavi: bool,
    pub v15: bool,
    pub v16_showtoucheffect: bool,
    pub v17_showscenetitle: bool,
    pub v18_showsongtitle: bool,
    pub v19: u32,
}

impl Settings {
    fn read(reader: &mut BitBuffer) -> bit_read::Result<Self> {
        reader.align();

        let v0_bgmvol = reader.read_int(7)?;
        let v1_sfxvol = reader.read_int(7)?;
        let v2_voicevol = reader.read_int(7)?;
        let v3_sysvol = reader.read_int(7)?;
        let v4_voicefocus = reader.read_bool()?;
        let v5_voicepanapot = reader.read_bool()?;
        let v6 = reader.read_bool()?;
        let v7 = reader.read_int(2)?;
        let v8 = reader.read_int(2)?;
        let v9_msgspeed = reader.read_int(7)?;
        let v10_skipspeed = reader.read_int(7)?;
        let v11_disallowskipunread = reader.read_bool()?;
        let v12 = reader.read_bool()?;
        let v13_msgwinalpha = reader.read_int(7)?;
        let v14_showroutenavi = reader.read_bool()?;
        let v15 = reader.read_bool()?;
        let v16_showtoucheffect = reader.read_bool()?;
        let v17_showscenetitle = reader.read_bool()?;
        let v18_showsongtitle = reader.read_bool()?;
        let v19 = reader.read_int(32)?;

        Ok(Self {
            v0_bgmvol,
            v1_sfxvol,
            v2_voicevol,
            v3_sysvol,
            v4_voicefocus,
            v5_voicepanapot,
            v6,
            v7,
            v8,
            v9_msgspeed,
            v10_skipspeed,
            v11_disallowskipunread,
            v12,
            v13_msgwinalpha,
            v14_showroutenavi,
            v15,
            v16_showtoucheffect,
            v17_showscenetitle,
            v18_showsongtitle,
            v19,
        })
    }

    fn write(&self, writer: &mut BitBuffer) {
        let &Self {
            v0_bgmvol,
            v1_sfxvol,
            v2_voicevol,
            v3_sysvol,
            v4_voicefocus,
            v5_voicepanapot,
            v6,
            v7,
            v8,
            v9_msgspeed,
            v10_skipspeed,
            v11_disallowskipunread,
            v12,
            v13_msgwinalpha,
            v14_showroutenavi,
            v15,
            v16_showtoucheffect,
            v17_showscenetitle,
            v18_showsongtitle,
            v19,
        } = self;

        writer.write_int(7, v0_bgmvol);
        writer.write_int(7, v1_sfxvol);
        writer.write_int(7, v2_voicevol);
        writer.write_int(7, v3_sysvol);
        writer.write_bool(v4_voicefocus);
        writer.write_bool(v5_voicepanapot);
        writer.write_bool(v6);
        writer.write_int(2, v7);
        writer.write_int(2, v8);
        writer.write_int(7, v9_msgspeed);
        writer.write_int(7, v10_skipspeed);
        writer.write_bool(v11_disallowskipunread);
        writer.write_bool(v12);
        writer.write_int(7, v13_msgwinalpha);
        writer.write_bool(v14_showroutenavi);
        writer.write_bool(v15);
        writer.write_bool(v16_showtoucheffect);
        writer.write_bool(v17_showscenetitle);
        writer.write_bool(v18_showsongtitle);
        writer.write_int(32, v19);
    }
}

/// Stores minimal info necessary to load a save.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GameData {
    pub date_time: NaiveDateTime,
    pub entry: GameDataEntry,
}

impl GameData {
    fn read(reader: &mut BitBuffer) -> bit_read::Result<Self> {
        let date = read_date_time(reader)?;
        let v6_arr_count: u32 = reader.read_int(1)?;
        assert_eq!(v6_arr_count, 0);

        let entry = GameDataEntry::read(reader)?;

        Ok(Self {
            date_time: date,
            entry,
        })
    }

    fn write(&self, writer: &mut BitBuffer) {
        let Self { date_time, entry } = self;

        write_date_time(date_time, writer);
        writer.write_int(1, 0); // v6_arr_count
        GameDataEntry::write(entry, writer)
    }
}

fn read_date_time(reader: &mut BitBuffer) -> bit_read::Result<NaiveDateTime> {
    let year: u32 = reader.read_int(12)?;
    let month = reader.read_int(4)?;
    let day = reader.read_int(5)?;
    let hour = reader.read_int(5)?;
    let minute = reader.read_int(6)?;
    let second = reader.read_int(6)?;

    let datetime = NaiveDate::from_ymd_opt(year as i32, month, day)
        .and_then(|date| date.and_hms_opt(hour, minute, second))
        .expect("invalid date");

    Ok(datetime)
}

fn write_date_time(value: &NaiveDateTime, writer: &mut BitBuffer) {
    writer.write_int(12, value.year());
    writer.write_int(4, value.month());
    writer.write_int(5, value.day());
    writer.write_int(5, value.hour());
    writer.write_int(6, value.minute());
    writer.write_int(6, value.second());
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GameDataEntry {
    pub scenario_id: i32,
    pub random_seed: u32,
    pub save_position: u32,
    pub selection_data: SelectionData,
}

impl GameDataEntry {
    fn read(reader: &mut BitBuffer) -> bit_read::Result<Self> {
        reader.align();

        let scenario_id = reader.read_int(32)?;
        let random_seed = reader.read_int(32)?;
        let save_position = reader.read_int(32)?;
        let selection_data = SelectionData::read(reader)?;

        Ok(Self {
            scenario_id,
            random_seed,
            save_position,
            selection_data,
        })
    }

    fn write(&self, writer: &mut BitBuffer) {
        let &Self {
            scenario_id,
            random_seed,
            save_position,
            ref selection_data,
        } = self;

        writer.align();

        writer.write_int(32, scenario_id);
        writer.write_int(32, random_seed);
        writer.write_int(32, save_position);
        SelectionData::write(selection_data, writer);
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SelectionData(Vec<u8>);

impl SelectionData {
    fn read(reader: &mut BitBuffer) -> bit_read::Result<Self> {
        let data = bit_read::read_vec(reader, bit_read::read_u32, bit_read::read_u8)?;

        Ok(Self(data))
    }

    fn write(&self, writer: &mut BitBuffer) {
        bit_write::write_vec(&self.0, writer, bit_write::write_u32, bit_write::write_u8);
    }
}

