    fn clean_snapshot() {
        let savedata = SaveData::decode(TEST_CLEAN_SAVE).unwrap();

        assert_ron_snapshot!("decoded, clean save", savedata);
    }

    #[test]
    fn roundtrip_clean_snapshot() {
        let deobfuscated = SaveData::deobfuscate(TEST_CLEAN_SAVE).unwrap();

        let decoded = SaveData::decode_raw(deobfuscated.clone()).unwrap();

        let reencoded = decoded.encode_raw();

        assert_eq!(&reencoded, &deobfuscated);
    }
